/**
 * Handler class for ContactTrigger.
 * Keeps the trigger thin; all logic lives here.
 *
 * SOQL budget (per transaction):
 *   - handleBefore        : 1 SOQL (Account lookup for before context)
 *   - handleAfterInsert   : 1 SOQL (Account lookup for after context)
 *   Total SOQL queries   : 2
 *
 * DML budget (per transaction):
 *   - handleAfterInsert   : 1 DML (single update of Account list)
 *   Total DML statements : 1
 */
public with sharing class ContactTriggerHandler {

    /**
     * Before insert / before update.
     * Copies BillingCountry → MailingCountry and (on insert) AccountSource → LeadSource
     * from the related Account, but only when the Contact field is currently blank.
     */
    public static void handleBefore(List<Contact> newRecords, Boolean isInsert) {
        // Collect unique Account Ids (single query instead of per-row query)
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL
        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newRecords) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = acctMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert.
     * When a Contact has a Phone and its Account's Phone is blank, copy the
     * Contact phone to the Account.  If several Contacts in the same batch share
     * an Account, only the FIRST Contact (in Trigger.new order) claims the slot.
     */
    public static void handleAfterInsert(List<Contact> newRecords) {
        // Collect unique Account Ids we need to check (contact has phone + account id)
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL – fetch current Phone values for all relevant accounts
        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Set<Id>   claimedAccounts = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();

        // Iterate in trigger order so the FIRST contact per account claims the slot
        for (Contact c : newRecords) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            // Once an account slot is claimed, later contacts in this batch cannot override it
            if (claimedAccounts.contains(c.AccountId)) {
                continue;
            }
            Account a = acctMap.get(c.AccountId);
            if (a != null && String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
                claimedAccounts.add(c.AccountId);
            }
        }

        // 1 DML
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
