public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> groupedByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return groupedByDomain;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }

        if (validAccountIds.isEmpty()) {
            return groupedByDomain;
        }

        if (!Schema.SObjectType.Contact.getDescribe().isQueryable() ||
            !Schema.SObjectType.Contact.fields.Email.getDescribe().isAccessible() ||
            !Schema.SObjectType.Contact.fields.AccountId.getDescribe().isAccessible()) {
            return groupedByDomain;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :validAccountIds
            AND Email != null
            WITH SECURITY_ENFORCED
        ];

        for (Contact contact : contacts) {
            if (contact == null || contact.Id == null || contact.Email == null || contact.AccountId == null) {
                continue;
            }

            String email = contact.Email.trim();
            if (String.isBlank(email)) {
                continue;
            }

            Integer atIndex = email.lastIndexOf('@');
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIndex + 1).trim().toLowerCase();
            if (String.isBlank(domain)) {
                continue;
            }

            if (!groupedByDomain.containsKey(domain)) {
                groupedByDomain.put(domain, new List<Contact>());
            }

            groupedByDomain.get(domain).add(contact);
        }

        return groupedByDomain;
    }
}
