```java
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return doSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException ex) {
            throw ex;
        } catch (Exception ex) {
            SearchException se = new SearchException();
            se.setMessage('Unexpected error: ' + ex.getMessage());
            throw se;
        }
    }

    // ------------------------------------------------------------------ private
    private static List<SObject> doSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // --- maxRows validation ---
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            fail('maxRows must be between 1 and 200');
        }

        // --- fields validation ---
        if (fields == null || fields.isEmpty()) {
            fail('fields must not be null or empty');
        }

        // --- object resolution (case-insensitive) ---
        if (String.isBlank(objectApiName)) {
            fail('objectApiName must not be blank');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String objLower = objectApiName.toLowerCase();
        Schema.SObjectType sObjType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == objLower) {
                sObjType = globalDescribe.get(key);
                break;
            }
        }
        if (sObjType == null) {
            fail('Object "' + objectApiName + '" does not exist');
        }

        Schema.SObjectDescribe sObjDescribe = sObjType.getDescribe();
        if (!sObjDescribe.isAccessible()) {
            fail('Running user cannot read object "' + sObjType.getDescribe().getName() + '"');
        }

        // --- build case-insensitive field lookup ---
        Map<String, Schema.SObjectField> fieldMap = sObjDescribe.fields.getMap();

        // Helper to resolve a field name (returns lowercase key or null)
        // and validate accessibility.

        // --- validate SELECT fields (FLS + existence) ---
        List<String> selectParts = new List<String> { 'Id' };
        Set<String> selectLower = new Set<String> { 'id' };

        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) continue;
            String lower = fieldName.toLowerCase();
            if (selectLower.contains(lower)) continue; // skip duplicate Id

            if (!fieldMap.containsKey(lower)) {
                fail('Field "' + fieldName + '" does not exist on object');
            }
            Schema.SObjectField fld = fieldMap.get(lower);
            if (!fld.getDescribe().isAccessible()) {
                fail('Running user cannot read field "' + fieldName + '"');
            }
            selectParts.add(fieldName);
            selectLower.add(lower);
        }

        // --- validate filter fields (existence + FLS + filterable) ---
        List<String> whereParts = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) continue;
                String lower = filterKey.toLowerCase();

                if (!fieldMap.containsKey(lower)) {
                    fail('Filter field "' + filterKey + '" does not exist on object');
                }
                Schema.SObjectField fld = fieldMap.get(lower);
                if (!fld.getDescribe().isAccessible()) {
                    fail('Running user cannot read filter field "' + filterKey + '"');
                }
                if (!fld.getDescribe().isFilterable()) {
                    fail('Filter field "' + filterKey + '" cannot be used in a WHERE clause');
                }
            }

            // Build WHERE clause (iterate in deterministic order for testability)
            for (String filterKey : new List<String>(filters.keySet())) {
                if (String.isBlank(filterKey)) continue;
                String lower = filterKey.toLowerCase();
                Object val = filters.get(filterKey);
                String formattedVal = formatValue(val);
                whereParts.add(filterKey + ' = ' + formattedVal);
            }
        }

        // --- validate ORDER BY field ---
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            String lower = orderByField.toLowerCase();
            if (!fieldMap.containsKey(lower)) {
                fail('Order-by field "' + orderByField + '" does not exist on object');
            }
            Schema.SObjectField fld = fieldMap.get(lower);
            if (!fld.getDescribe().isAccessible()) {
                fail('Running user cannot read order-by field "' + orderByField + '"');
            }
            if (!fld.getDescribe().isSortable()) {
                fail('Field "' + orderByField + '" cannot be used in an ORDER BY clause');
            }
            orderClause = ' ORDER BY ' + orderByField + ' ASC';
        }

        // --- assemble SOQL ---
        String soql = 'SELECT ' + String.join(selectParts, ', ')
                    + ' FROM ' + sObjType.getDescribe().getName();

        if (!whereParts.isEmpty()) {
            soql += ' WHERE ' + String.join(whereParts, ' AND ');
        }
        soql += orderClause;
        soql += ' LIMIT ' + String.valueOf(maxRows);

        // Execute with sharing context (class is 'with sharing' → record sharing enforced)
        return Database.query(soql);
    }

    // ------------------------------------------------------------------ helpers

    /**
     * Formats a filter value for safe inclusion in a SOQL WHERE clause.
     * Handles String, Boolean, Integer, Long, Double, Decimal, Date, Datetime,
     * Id and null. Strings/Id are single-quoted and quote-escaped to prevent
     * SOQL injection.
     */
    private static String formatValue(Object val) {
        if (val == null) {
            return 'null';
        }
        if (val instanceof Boolean) {
            return (Boolean) val ? 'true' : 'false';
        }
        if (val instanceof Integer) {
            return String.valueOf((Integer) val);
        }
        if (val instanceof Long) {
            return String.valueOf((Long) val);
        }
        if (val instanceof Double) {
            return String.valueOf((Double) val);
        }
        if (val instanceof Decimal) {
            return String.valueOf((Decimal) val);
        }
        if (val instanceof Date) {
            return ((Date) val).formatGmt('yyyy-MM-dd');
        }
        if (val instanceof Datetime) {
            return ((Datetime) val).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
        }
        if (val instanceof Id) {
            return '\'' + String.escapeSingleQuotes(String.valueOf(val)) + '\'';
        }
        if (val instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) val) + '\'';
        }
        // Fallback – quote and escape
        return '\'' + String.escapeSingleQuotes(String.valueOf(val)) + '\'';
    }

    /**
     * Creates and throws a SearchException with the given message.
     */
    private static void fail(String msg) {
        SearchException se = new SearchException();
        se.setMessage(msg);
        throw se;
    }
}
