public with sharing class ContactLookupAction {

    @InvocableMethod(
        label = 'Find Contact by Email',
        description = 'Searches for a Contact by email address (case-insensitive, trimmed).',
        supportsPagination = true
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Fast path – nothing to look up
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Build the parallel key list (trimmed + lowercased) and collect unique keys
        List<String> keys = new List<String>(requests.size());
        Set<String> searchKeys = new Set<String>();

        for (Request req : requests) {
            String trimmed = (req != null && req.email != null)
                ? req.email.trim()
                : null;

            if (String.isBlank(trimmed)) {
                keys.add(null);
            } else {
                String key = trimmed.toLowerCase();
                keys.add(key);
                searchKeys.add(key);
            }
        }

        // Single SOQL query – one round-trip regardless of batch size
        List<Contact> contacts = searchKeys.isEmpty()
            ? new List<Contact>()
            : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :searchKeys
                ORDER BY CreatedDate ASC
              ];

        // Build a lookup keyed on normalised (trimmed + lowercased) email.
        // Because of the ASC ordering the FIRST contact we encounter per key
        // is the one with the earliest CreatedDate.
        Map<String, Id> earliestIdByNormalisedEmail = new Map<String, Id>();

        for (Contact c : contacts) {
            if (c.Email == null) continue;

            String cKey = c.Email.trim().toLowerCase();

            if (!earliestIdByNormalisedEmail.containsKey(cKey)) {
                earliestIdByNormalisedEmail.put(cKey, c.Id);
            }
        }

        // Build one Result per Request, preserving order
        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String key = keys[i];

            if (key != null && earliestIdByNormalisedEmail.containsKey(key)) {
                r.found    = true;
                r.contactId = earliestIdByNormalisedEmail.get(key);
            } else {
                r.found    = false;
                r.contactId = null;
            }

            results.add(r);
        }

        return results;
    }

    // ── Invocable input wrapper ──────────────────────────────────────────
    public class Request {
        @InvocableVariable(
            label    = 'Email',
            description = 'Email address to search for (case-insensitive, trimmed)',
            required = true
        )
        public String email;
    }

    // ── Invocable output wrapper ─────────────────────────────────────────
    public class Result {
        @InvocableVariable(label = 'Contact Id')
        public Id contactId;

        @InvocableVariable(label = 'Found')
        public Boolean found;
    }
}
