private class ShippingCostCalculatorTest {

    // ─── Weight validation ──────────────────────────────────────────────────────

    @IsTest
    static void testWeightNullThrows() {
        try {
            ShippingCostCalculator.quote(null, 'DOMESTIC', false, 50);
