public with sharing class LeadImportService {
    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertOriginalIndex = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            if (lead == null) {
                result.errorsByIndex.put(i, 'Null Lead.');
                continue;
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            Boolean isDuplicate = false;

            if (String.isNotBlank(lead.Email)) {
                String trimmedEmail = lead.Email.trim();

                if (String.isNotBlank(trimmedEmail)) {
                    String emailKey = trimmedEmail.toLowerCase();

                    if (seenEmails.contains(emailKey)) {
                        result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                        isDuplicate = true;
                    } else {
                        seenEmails.add(emailKey);
                    }
                }
            }

            if (isDuplicate) {
                continue;
            }

            lead.Id = null;
            toInsert.add(lead);
            toInsertOriginalIndex.add(i);
        }

        if (toInsert.isEmpty()) {
            result.successCount = result.insertedIds.size();
            return result;
        }

        try {
            Database.SaveResult[] saveResults = Database.insert(toInsert, false);

            for (Integer i = 0; i < saveResults.size(); i++) {
                Database.SaveResult saveResult = saveResults[i];
                Integer originalIndex = toInsertOriginalIndex[i];

                if (saveResult != null && saveResult.isSuccess()) {
                    if (saveResult.getId() != null) {
                        result.insertedIds.add(saveResult.getId());
                    }
                } else {
                    List<String> messages = new List<String>();

                    if (saveResult != null && saveResult.getErrors() != null) {
                        for (Database.Error error : saveResult.getErrors()) {
                            if (error != null && String.isNotBlank(error.getMessage())) {
                                messages.add(error.getMessage());
                            }
                        }
                    }

                    if (messages.isEmpty()) {
                        result.errorsByIndex.put(originalIndex, 'Lead import failed.');
                    } else {
                        result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
                    }
                }
            }
        } catch (DmlException e) {
            for (Integer i = 0; i < toInsert.size(); i++) {
                Integer originalIndex = toInsertOriginalIndex[i];
                result.errorsByIndex.put(originalIndex, e.getMessage());
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }
}
