```apex
/**
 * Central factory that wires together the UnitOfWork, Service, Selector and
 * Domain layers using fflib_Application factories.
 *
 * Fields are public static (non-final) so that test classes can replace
 * individual factories via setMock-style substitution.
 */
public with sharing class Application {

    /**
     * Service factory – maps each service interface to its implementation.
     */
    public static fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type> {
                IAccountsService.Class => AccountsServiceImpl.class
            }
        );

    /**
     * Selector factory – maps each SObjectType to its selector instance.
     */
    public static fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<Id, fflib_ISObjectSelector> {
                Account.SObjectType => new AccountsSelector(),
                Contact.SObjectType => new ContactsSelector()
            }
        );

    /**
     * Domain factory – maps each SObjectType to its domain constructor.
     */
    public static fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(
            new Map<SObjectType, fflib_SObjectDomain.IConstructable> {
                Account.SObjectType => new Accounts.Constructor()
            }
        );

    /**
     * UnitOfWork factory – declares the SObject types that may participate
     * in a single unit of work, listed in parent→child / dependency order so
     * that one commitWork() can insert Accounts first, then their child
     * Contacts and Opportunities, then OpportunityContactRoles that link the
     * newly-created Opportunities and Contacts.
     */
    public static fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new SObjectType[] {
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

}
