    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            ((IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class))
                .startFulfilment(qualifyingIds);
        }
    }

    public override void onAfterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            if (opp.StageName == 'Closed Won'
                && Trigger.oldMap.get(opp.Id).StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            ((IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class))
                .startFulfilment(qualifyingIds);
        }
    }
}
