    private void validateAmountNotNegative() {
        for (SObject sobj : this.getRecords()) {
            Opportunity opp = (Opportunity) sobj;
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, 'Amount');
            }
        }
