    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> accountFieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            accountFieldNames.add(String.valueOf(f));
