```apex
/**
 * Service that creates Accounts and their related Contacts in a single
 * Unit of Work (fflib_ISObjectUnitOfWork) so that all DML is bulk-safe
 * and relationship fields are resolved correctly before the commit.
 */
public with sharing class AccountOnboardingService {

    /**
     * For every entry in the supplied map, creates one Account whose Name
     * equals the key and one Contact per last-name in the associated list.
     *
     * @param contactLastNamesByAccountName  mapping of Account Name → list of Contact LastNames
     * @return the newly created Accounts (Ids populated after commit)
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        // Guard: null / empty map → no work, return empty list
        if (contactLastNamesByAccountName == null
            || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // One UoW that handles Account then Contact inserts in dependency order
        fflib_ISObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new Schema.SObjectType[] {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {

            Account acct = new Account(Name = accountName);
            uow.registerNew(acct);
            newAccounts.add(acct);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            for (String lastName : lastNames) {
                if (String.isBlank(lastName)) {
                    continue;
                }

                Contact c = new Contact(LastName = lastName);

                // Register the child for insert and declare the deferred
                // relationship so the UoW stamps AccountId before the
                // Contact DML executes (avoids hard-coding the Id).
                uow.registerNew(c);
                uow.registerRelationship(c, Contact.AccountId, acct);
            }
        }

        // Single bulk commit – Accounts inserted first, then Contacts
        // with their AccountId already populated.
        uow.commitWork();

        return newAccounts;
    }
}
