public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities via the Selector layer
        List<Opportunity> opps =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Filter out those already at Closed Won
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opps) {
            if (opp.StageName != 'Closed Won') {
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // Obtain a single Unit of Work
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Opportunity opp : toClose) {
            // Update the opportunity
            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            // Queue a platform event for this deal
            Deal_Won__e evt = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c        = opp.Amount
            );
            uow.registerPublish(evt);
        }

        // commit() executes the DML first; platform events are published
        // only after all DML succeeds. A DML exception propagates here and
        // no Deal_Won__e is published.
        uow.commit();

        return toClose.size();
    }
}
