```java
public with sharing class AccountRatingService {

    /**
     * Recalculates the Rating picklist on every Account in the supplied
     * list based on the Account's *current* set of open opportunities.
     *
     *   Hot   – ≥ 1 open Opportunity with Amount ≥ 100 000
     *   Warm  – ≥ 1 open Opportunity, none ≥ 100 000
     *   Cold  – no open Opportunities
     *
     * Runs asynchronously so the synchronous Opportunity transaction stays
     * inside its CPU-time budget even when 200 records are saved.
     */
    @future
    public static void recalculate(List<Id> accountIds) {

        // Defensive copy – @future params are serialised; guard against
        // an empty or duplicate-laden list coming from the trigger.
        Set<Id> accIdSet = new Set<Id>(accountIds);
        if (accIdSet.isEmpty()) {
            return;
        }

        // Single SOQL for every relevant Account (bulk-safe).
        // IsClosed = false covers "Open" stages (Prospecting,
        // Needs Analysis, …) while excluding Closed Won / Closed Lost.
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : [
            SELECT Id, AccountId, Amount, StageName
            FROM   Opportunity
            WHERE  AccountId IN :accIdSet
              AND  IsClosed = false
        ]) {
            if (!oppsByAccount.containsKey(opp.AccountId)) {
                oppsByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            oppsByAccount.get(opp.AccountId).add(opp);
        }

        List<Account> toUpdate = new List<Account>();

        for (Id accId : accIdSet) {
            Account acc = new Account(Id = accId);

            List<Opportunity> openOpps = oppsByAccount.get(accId);

            if (openOpps == null || openOpps.isEmpty()) {
                // No open pipeline at all → Cold
                acc.Rating = 'Cold';
            } else {
                Boolean hasHotOpp = false;
                for (Opportunity o : openOpps) {
                    if (o.Amount != null && o.Amount >= 100000) {
                        hasHotOpp = true;
                        break;                       // short-circuit
                    }
                }
                acc.Rating = hasHotOpp ? 'Hot' : 'Warm';
            }

            toUpdate.add(acc);
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
