public with sharing class LineItemDiscountHandler {

    /**
     * Called from the before-insert trigger.
     *
     * @param lines The list of newly-inserted OpportunityLineItem records
     *              (Trigger.new).
     */
    public static void applyDefaultDiscount(List<OpportunityLineItem> lines) {

        // Cache by Product2Id so we never call PricingRules more than once
        // per distinct product (PricingRules.standardDiscountFor contains a
        // SOQL query internally – see caveat below).
        Map<Id, Decimal> discountCache = new Map<Id, Decimal>();

        for (OpportunityLineItem line : lines) {

            // A rep or CPQ import that explicitly set Discount (including 0)
            // keeps that value untouched.
            if (line.Discount != null) {
                continue;
            }

            Id productId = line.Product2Id;
            if (productId == null) {
                continue; // defensive – shouldn't happen, but guard against it
            }

            Decimal standardDiscount;

            if (discountCache.containsKey(productId)) {
                standardDiscount = discountCache.get(productId);
            } else {
                // Single source of truth for the percentage lookup.
                standardDiscount = PricingRules.standardDiscountFor(productId);
                discountCache.put(productId, standardDiscount);
            }

            line.Discount = standardDiscount;
        }
    }
}
