File: force-app/main/default/triggers/CaseTrigger.trigger

```apex
/*
 * CaseTrigger (after update)
 *
 * When a Case transitions from Open → Closed AND has a Contact,
 * a CSAT-survey Task is created asynchronously via a Queueable job.
 * One Queueable job is enqueued per case so that a failure in one
 * survey cannot cascade to the others.
 *
 * NOTE – Queueable enqueue limit (50 / transaction):
 *   The nightly bulk-close of up to 200 cases must be split into
 *   API batches of ≤ 50 records, OR handled via a BatchApex wrapper,
 *   otherwise the 50-enqueue-per-transaction governor limit is hit.
 */
trigger CaseTrigger on Case (after update) {

    if (Trigger.isAfter && Trigger.isUpdate) {

        Integer enqueued = 0;
        final Integer MAX_QUEUEABLE_PER_TX = 50;

        for (Case newCase : Trigger.new) {

            Case oldCase = Trigger.oldMap.get(newCase.Id);

            // Only fire on the transition Open → Closed
            if (!newCase.IsClosed || oldCase.IsClosed) {
                continue;
            }

            // A case without a Contact can never receive a survey
            if (newCase.ContactId == null) {
                continue;
            }

            // Stay within the per-transaction Queueable limit
            if (enqueued >= MAX_QUEUEABLE_PER_TX) {
                // In a real org, log or queue a platform event / custom
                // object so the remaining cases are retried in a second pass.
                // Here we simply stop to avoid a LimitException that would
                // roll back the entire DML.
                break;
            }

            System.enqueueJob(new CaseSurveyJob(newCase.Id));
            enqueued++;
        }
    }
}
```

