```apex
/**
 * CaseSurveyJob
 *
 * Queueable class executed asynchronously (triggered by CaseTrigger).
 * Creates a one-off Task (CSAT survey activity) linked to a single Case
 * and its Contact.
 *
 * Runs in its own transaction → a Task-insert failure here does NOT
 * affect any other case's survey.
 */
public with sharing class CaseSurveyJob implements System.Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(System.Queueable.Context ctx) {

        // Re-query the Case: by the time this async job fires the
        // parent transaction may have been committed, the case may have
        // been re-assigned, its Contact swapped, or it may no longer exist.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM   Case
            WHERE  Id = :caseId
            LIMIT  1
        ];

        if (cases.isEmpty()) {
            // Case was deleted between trigger and queue execution – nothing to do.
            return;
        }

        Case c = cases[0];

        // Double-check pre-conditions (defence-in-depth; trigger already
        // guarded, but the case state could have changed since enqueue time).
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task();
        surveyTask.WhatId       = c.Id;
        surveyTask.WhoId        = c.ContactId;
        surveyTask.Subject      = 'CSAT survey: ' + c.CaseNumber;
        surveyTask.ActivityDate = Date.today().addDays(2);
        surveyTask.Status       = 'Not Started';

        insert surveyTask;
    }
}
```

