```java
/**
 * Handler for AccountTrigger (after update).
 *
 * When an Account's BillingCountry changes, every Contact under that Account
 * whose MailingCountry is blank or equals the Account's *previous* BillingCountry
 * gets its MailingCountry set to the new BillingCountry.
 *
 * Design notes
 * ────────────
 * • One SOQL per transaction, scoped to only the affected AccountIds.
 *   A blanket "SELECT … FROM Contact" would scan ~2.3 M rows and exceed the
 *   50 K row / heap governor limits on the very first MDM batch.
 * • Trigger.new is already bounded to ≤ 200 Accounts (MDM batch size), so the
 *   affected-AccountId set is small and the WHERE-IN filter keeps the Contact
 *   query well inside limits even with millions of Contacts in the org.
 * • No SOQL inside any loop – the single query sits at the top of the method.
 */
public with sharing class AccountCountrySync {

    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {

        // ---- 1. Identify accounts whose BillingCountry actually changed ----------
        Map<Id, String> prevCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newCountryByAccountId  = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account prev = oldAccountMap.get(acc.Id);
            // Treat any difference (including null→"US" or "US"→null) as a change.
            if (acc.BillingCountry != prev.BillingCountry) {
                prevCountryByAccountId.put(acc.Id, prev.BillingCountry);   // may be null
                newCountryByAccountId.put(acc.Id, acc.BillingCountry);     // may be null
            }
        }

        if (prevCountryByAccountId.isEmpty()) {
            return; // nothing to do – avoids the SOQL entirely
        }

        // ---- 2. Single query scoped to the affected accounts ---------------------
        // Replaces the original "SELECT … FROM Contact" (all 2.3 M rows).
        // Now only pulls contacts belonging to the ≤ 200 accounts that moved.
        List<Contact> candidates = [
            SELECT Id, AccountId, MailingCountry
            FROM   Contact
            WHERE  AccountId IN :prevCountryByAccountId.keySet()
        ];

        // ---- 3. Filter & build the update list -----------------------------------
        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : candidates) {
            String previousCountry = prevCountryByAccountId.get(c.AccountId);

            // Update only when MailingCountry is blank
            // or equals the account's previous BillingCountry.
            if (String.isBlank(c.MailingCountry)
                || c.MailingCountry == previousCountry) {

                c.MailingCountry = newCountryByAccountId.get(c.AccountId);
                toUpdate.add(c);
            }
        }

        // ---- 4. DML --------------------------------------------------------------
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

