import { LightningElement } from 'lwc';

/**
 * Module-level counter to guarantee a unique element id for each component
 * instance (used by aria-controls so assistive tech can associate the
 * toggle button with its disclosure region).
 */
let instanceCounter = 0;

export default class CollapsibleSection extends LightningElement {
    // ----- private reactive state -------------------------------------------------

    /** @type {boolean} true = expanded, false = collapsed (starts collapsed). */
    expanded = false;

    /**
     * Unique per-instance id rendered on the .section-body <div>.
     * Generated once at construction so the id never changes across re-renders,
     * keeping the aria-controls ↔ id reference stable.
     */
    sectionBodyId = `section-body-${++instanceCounter}`;

    // ----- template-bound getters -------------------------------------------------

    /**
     * Returns the *string* "true" or "false" so the rendered attribute always
     * matches the WAI-ARIA disclosure pattern (e.g. aria-expanded="true").
     * Using a getter guarantees the attribute is always present (aria-expanded is
     * NOT a boolean HTML attribute – omitting it would break the ARIA pattern).
     */
    get ariaExpanded() {
        return this.expanded ? 'true' : 'false';
    }

    /**
     * Bound to the `hidden` attribute on the .section-body <div>.
     *   – collapsed → hidden=true  →  `hidden` attribute present  (screen readers &
     *                                 browser skip the content)
     *   – expanded  → hidden=false →  `hidden` attribute absent   (content visible)
     *
     * The <div> is always in the DOM so `aria-controls` always resolves, satisfying
     * the requirement that the reference never dangles.
     */
    get hidden() {
        return !this.expanded;
    }

    // ----- event handler ----------------------------------------------------------

    /**
     * Toggle handler wired via onclick in the template.
     * No need to call preventDefault / stopPropagation; this is the only
     * listener on the button.
     */
    toggle() {
        this.expanded = !this.expanded;
    }
}
