        if (allValid) {
            this.showError = false;
            const results = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: results }
                })
            );
        } else {
            this.showError = true;
        }
    }
