import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PRIVATE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    @track fields = { fullName: '', email: '', company: '' };

    handleChange(event) {
        const field = event.target?.dataset?.field;

        if (!field) {
            return;
        }

        const detailValue = event.detail?.value;
        const value =
            detailValue !== undefined
                ? detailValue
                : event.target
                  ? event.target.value
                  : undefined;

        this.fields = {
            ...this.fields,
            [field]: value === undefined ? '' : value
        };
    }

    handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');

        if (emailInput) {
            const email = (this.fields.email || '').trim();
            const atIndex = email.lastIndexOf('@');
            const domain = atIndex >= 0 ? email.substring(atIndex + 1).toLowerCase() : '';

            if (PRIVATE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let isValid = true;
        const inputs = this.template.querySelectorAll('lightning-input');

        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                isValid = false;
            }
        });

        if (!isValid) {
            return;
        }

        register({
            fullName: this.fields.fullName,
            email: this.fields.email,
            company: this.fields.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: '',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error?.body?.message,
                        variant: 'error'
                    })
                );
            });
    }
}
