import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @track _activeIndex = 0;

    _label = '';
    _options = [];
    _value = '';

    /* ---------- public API (getters / setters) ---------- */

    @api
    get label() {
        return this._label;
    }
    set label(val) {
        this._label = val || '';
    }

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val ? [...val] : [];
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        const next = val || '';
        if (next !== this._value) {
            this._value = next;
            this._syncActiveIndex();
        }
    }

    /* ---------- computed helpers ---------- */

    get hasOptions() {
        return Array.isArray(this._options) && this._options.length > 0;
    }

    get activeOptionId() {
        if (!this.hasOptions) {
            return '';
        }
        return 'statusListbox-opt-' + this._activeIndex;
    }

    get optionItems() {
        if (!this.hasOptions) {
            return [];
        }
        return this._options.map((opt, idx) => ({
            ...opt,
            id: 'statusListbox-opt-' + idx,
            selected: opt.value === this._value ? 'true' : 'false'
        }));
    }

    /* ---------- private ---------- */

    _syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    _select(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        const opt = this._options[index];
        if (opt.value === this._value) {
            return; // already selected – do nothing
        }
        this._value = opt.value;
        this._activeIndex = index;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }

    /* ---------- template event handlers ---------- */

    handleKeyDown(event) {
        const NAV_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!NAV_KEYS.includes(event.key)) {
            return; // allow default (Tab, etc.)
        }

        event.preventDefault();

        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }

        let next = this._activeIndex;

        switch (event.key) {
            case 'ArrowDown':
                if (this._activeIndex < lastIndex) {
                    next = this._activeIndex + 1;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    next = this._activeIndex - 1;
                }
                break;
            case 'Home':
                next = 0;
                break;
            case 'End':
                next = lastIndex;
                break;
            case 'Enter':
            case ' ':
                this._select(this._activeIndex);
                return;
        }

        if (next !== this._activeIndex) {
            this._activeIndex = next;
        }
    }

    handleOptionClick(event) {
        const el = event.currentTarget;
        const value = el.dataset.value;
        const idx = this._options.findIndex((o) => o.value === value);
        if (idx >= 0) {
            this._select(idx);
        }
    }
}
