```java
/**
 * Service for setting a Contact's current primary employer (Organization Account)
 * in the NPSP Household Account model with Affiliations enabled.
 *
 * After execution:
 *   • A Current / Primary npe5__Affiliation__c exists linking the Contact to the
 *     target Organization Account (created or reactivated if one already exists).
 *   • Contact.npsp__Primary_Affiliation__c points to that Organization Account.
 *   • The Contact's AccountId (Household) is never modified.
 *   • If the Organization is already the Contact's primary employer the Contact
 *     is left completely untouched (no duplicate Affiliation, no unnecessary DML).
 *   • NPSP's own trigger logic handles retiring the PREVIOUS primary employer
 *     (Former, non-primary, end-date = today) via its standard mechanism.
 *
 * Governor limits honoured: ≤ 2 SOQL, ≤ 2 DML regardless of collection size.
 */
public with sharing class EmployerService {

    /**
     * @param employerByContactId  Contact Id → Organization (Account) Id.
     *        Null keys/values are silently ignored.  A null or empty map is a no-op.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ── guard ──────────────────────────────────────────────────────────────
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Strip entries whose value (org Account) is null.
        Map<Id, Id> validEntries = new Map<Id, Id>();
        for (Id cId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(cId);
            if (orgId != null) {
                validEntries.put(cId, orgId);
            }
        }
        if (validEntries.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(validEntries.keySet());
        Set<Id> orgIds     = new Set<Id>(validEntries.values());

        // ── SOQL 1 : existing Current Affiliations for the relevant pairs ────
        //    Key = "ContactId-OrgId" so we can detect "already exists" without
        //    creating a duplicate npe5__Affiliation__c row.
        Map<Id, npe5__Affiliation__c> existingAffMap = new Map<Id, npe5__Affiliation__c>();

        for (npe5__Affiliation__c a : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Primary__c,
                   npe5__Status__c
            FROM   npe5__Affiliation__c
            WHERE  npe5__Contact__c      IN :contactIds
              AND  npe5__Organization__c  IN :orgIds
              AND  npe5__Status__c        = 'Current'
        ]) {
            // Composite key so (Contact A, Org X) and (Contact A, Org Y) don't collide.
            Id compoundKey = Id.valueOf(a.npe5__Contact__c.substring(0,15)
                                      + a.npe5__Organization__c.substring(0,15));
            existingAffMap.put(compoundKey, a);
        }

        // ── SOQL 2 : Contact records (current primary lookup + household) ─────
        List<Contact> contacts = [
            SELECT Id,
                   npsp__Primary_Affiliation__c,
                   AccountId
            FROM   Contact
            WHERE  Id IN :contactIds
