public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU Allocations on the given Opportunity with one allocation
     * per entry in <em>percentByGauId</em>.  Setting npsp__Percent__c on each
     * Allocation ensures NPSP auto-recalculates the amount when the Opportunity
     * Amount changes later (no further code needed).
     *
     * @param opportunityId   Id of the Opportunity whose allocations to rebuild.
     * @param percentByGauId  GAU Id → percentage (60 means 60 %).
     * @return               The newly-inserted Allocation__c records.
     * @throws AllocationException on invalid input or inactive GAUs.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ── Validate: map must be non-null and non-empty ──────────────
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Allocation map is null or empty.');
        }

        // ── Validate: every percentage is non-null and > 0, total ≤ 100 ─
        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Every allocation percentage must be greater than 0.'
                );
            }
            totalPercent += pct;
        }
        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages sum to ' + totalPercent + '; maximum is 100.'
            );
        }

        // ── Validate: every GAU must exist AND be active ───────────────
        Set<Id> gauIds = new Set<Id>(percentByGauId.keySet());
        List<npsp__General_Accounting_Unit__c> activeGaus = [
            SELECT Id
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
              AND npsp__Active__c = true
            WITH SECURITY_ENFORCED
        ];
        if (activeGaus.size() != percentByGauId.size()) {
            throw new AllocationException(
                'One or more General Accounting Units are inactive or not found.'
            );
        }

        // ── Fetch the Opportunity amount (needed for initial Amount__c) ─
        List<Opportunity> opps = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException(
                'Opportunity ' + opportunityId + ' not found.'
            );
        }
        Decimal oppAmount = (opps[0].Amount != null) ? opps[0].Amount : 0;

        // ── All validations passed – safe to mutate data ────────────────

        // Remove every existing Allocation on this Opportunity.
        DELETE [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        // Build one Allocation per map entry.
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c              = opportunityId,
                npsp__General_Accounting_Unit__c  = gauId,
                npsp__Percent__c                  = pct,
                npsp__Amount__c                   = (oppAmount * pct) / 100
            );
            allocations.add(alloc);
        }

        insert allocations;

        return allocations;
    }
}
