/**
 * Service to create or update NPSP Partial Soft Credits and the
 * associated Opportunity Contact Role on the Household Account model.
 *
 * Budget for a 200-request batch: ≤ 3 SOQL / ≤ 4 DML.
 */
public with sharing class SoftCreditService {

    // ── Exception ──────────────────────────────────────────────────────
    public class SoftCreditException extends Exception {}

    // ── Request DTO ────────────────────────────────────────────────────
    public class SoftCreditRequest {
        public Id     opportunityId;
        public Id     contactId;
        public Decimal amount;
        public String role;
    }

    // ── Public entry-point ─────────────────────────────────────────────
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {

        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ── 1. Collect unique Ids ──────────────────────────────────────
        Set<Id> oppIds     = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ── 2. SOQL #1 – Opportunities (validation data) ──────────────
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id,
                    npsp__Primary_Contact__c,
                    Amount
             FROM   Opportunity
             WHERE  Id IN :oppIds]
        );

        // ── 3. SOQL #2 – Existing Opportunity Contact Roles ───────────
        // Composite key: "oppId|contactId"
        Map<String, OpportunityContactRole> existingOcrMap =
            new Map<String, OpportunityContactRole>();

        for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role
                FROM   OpportunityContactRole
                WHERE  OpportunityId IN :oppIds
                   AND ContactId   IN :contactIds
              ]) {
            String key = ocr.OpportunityId + '|' + ocr.ContactId;
            existingOcrMap.put(key, ocr);
        }

        // ── 4. SOQL #3 – Existing Partial Soft Credits ────────────────
        Map<String, npsp__Partial_Soft_Credit__c> existingPscMap =
            new Map<String, npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c psc : [
                SELECT Id,
                       npsp__Opportunity__c,
                       npsp__Contact_Name__c,
                       npsp__Amount__c,
                       npsp__Role_Name__c,
                       npsp__Contact_Role_ID__c
                FROM   npsp__Partial_Soft_Credit__c
                WHERE  npsp__Opportunity__c   IN :oppIds
                   AND npsp__Contact_Name__c IN :contactIds
              ]) {
            String key = psc.npsp__Opportunity__c + '|' + psc.npsp__Contact_Name__c;
            existingPscMap.put(key, psc);
        }

        // ── 5. Validate (pre-DML, throws → nothing persisted) ──────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact of Opportunity ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for Opportunity ' + req.opportunityId);
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount exceeds Opportunity amount for Opportunity ' + req.opportunityId);
            }
        }

        // ── 6. Build composite keys once ───────────────────────────────
        List<String> keys = new List<String>(requests.size());
        for (SoftCreditRequest req : requests) {
            keys.add(req.opportunityId + '|' + req.contactId);
        }

        // ── 7. Pass A – resolve / create OpportunityContactRoles ──────
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();

        // After DML we need the Id of the single OCR per (opp,contact).
        // Pre-populate with existing records so we can skip the second query.
        Map<String, OpportunityContactRole> resolvedOcrMap =
            new Map<String, OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req  = requests[i];
            String           key  = keys[i];
            OpportunityContactRole existingOcr = existingOcrMap.get(key);

            if (existingOcr != null) {
                if (existingOcr.Role != req.role) {
                    existingOcr.Role = req.role;
                    ocrsToUpdate.add(existingOcr);
                }
                resolvedOcrMap.put(key, existingOcr);
            } else {
                ocrsToInsert.add(new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role,
                    IsPrimary     = false
                ));
                // Resolved after insert (Id not yet available)
            }
        }

        // ── DML #1 & #2 ───────────────────────────────────────────────
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        // Populate resolvedOcrMap with newly-inserted OCRs (Id now available)
        for (OpportunityContactRole newOcr : ocrsToInsert) {
            String key = newOcr.OpportunityId + '|' + newOcr.ContactId;
            resolvedOcrMap.put(key, newOcr);
        }

        // ── 8. Pass B – resolve / create / update Partial Soft Credits ─
        List<npsp__Partial_Soft_Credit__c> pscsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            String          key  = keys[i];

            OpportunityContactRole      ocr         = resolvedOcrMap.get(key);
            npsp__Partial_Soft_Credit__c existingPsc = existingPscMap.get(key);

            if (existingPsc != null) {
                // Update in place – no second PSC row per (opp, contact)
                existingPsc.npsp__Amount__c     = req.amount;
                existingPsc.npsp__Role_Name__c  = req.role;
                if (ocr != null) {
                    existingPsc.npsp__Contact_Role_ID__c = (String) ocr.Id;
                }
                pscsToUpdate.add(existingPsc);
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c       = req.opportunityId,
                    npsp__Contact_Name__c      = req.contactId,
                    npsp__Amount__c            = req.amount,
                    npsp__Role_Name__c         = req.role,
                    npsp__Contact_Role_ID__c   = (ocr != null) ? (String) ocr.Id : null
                );
                pscsToInsert.add(newPsc);
            }
        }

        // ── DML #3 & #4 ───────────────────────────────────────────────
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
