public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {

        // ── Validate numberOfPayments ──────────────────────────────────────────
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be a positive integer.');
        }

        // ── Load the opportunity and its payments (no DML yet) ────────────────
        List<Opportunity> oppList = [
            SELECT Id, Amount, IsClosed,
                   (SELECT Id,
                           npe01__Payment_Amount__c,
                           npe01__Paid__c,
                           npe01__Written_Off__c
                      FROM npe01__OppPayment__r)
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (oppList.isEmpty() || oppList[0].IsClosed) {
            throw new PaymentPlanException(
                'Opportunity is closed or does not exist.');
        }

        Opportunity opp = oppList[0];
        Decimal oppAmount = opp.Amount == null ? 0 : opp.Amount;

        // ── Determine outstanding amount & collect payments to delete ──────────
        Decimal outstanding = oppAmount;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : opp.npe01__OppPayment__r) {
            if (p.npe01__Paid__c || p.npe01__Written_Off__c) {
                // History – leave untouched, but reduce the outstanding balance
                Decimal pAmt = p.npe01__Payment_Amount__c == null
                    ? 0 : p.npe01__Payment_Amount__c;
                outstanding -= pAmt;
            } else {
                // Unpaid & not written-off – schedule for deletion
                toDelete.add(p);
            }
        }

        // ── Validate outstanding amount (still no DML) ────────────────────────
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount is not greater than zero.');
        }

        // ── Delete the old non-history payments ───────────────────────────────
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // ── Compute per-installment amount (truncated to 2 dp) ────────────────
        //   Each installment (except the last) gets floor(outstanding / n, 2).
        //   The last installment absorbs the rounding remainder so the total
        //   equals outstanding exactly.
        Decimal divisor = numberOfPayments;          // implicit widening to Decimal
        Decimal perPayment = outstanding.divide(divisor, 2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Decimal allocated = 0;

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amt;
            if (i == numberOfPayments - 1) {
                // Last installment takes the remainder
                amt = outstanding - allocated;
            } else {
                amt = perPayment;
                allocated += perPayment;
            }

            npe01__OppPayment__c pp = new npe01__OppPayment__c();
            pp.npe01__Opportunity__c    = opportunityId;
            pp.npe01__Payment_Amount__c = amt;
            pp.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            // Paid / Written_Off default to false → new payments are unpaid
            newPayments.add(pp);
        }

        insert newPayments;

        // Return in schedule order (already ordered by construction)
        return newPayments;
    }
}
