/**
 * Bulk-safe service that creates NPSP parent–child Relationships in both
 * directions with the correct reciprocal Type, skipping pairs that already
 * have any Relationship (in either direction).
 *
 * Governor-budget (per call, regardless of input size):
 *   1  SOQL  Contact            (child Gender for reciprocal Type lookup)
 *   1  SOQL  Relationship__c    (existing pairs – dedup guard)
 *   1  DML   insert             (all new records in one bulk statement)
 */
public with sharing class FamilyService {

    // ──────────────────────────────────────────────────────────────────
    //  Hard-coded reciprocal types that mirror the org's
    //  npe4__Relationship_Lookup__c record whose Name = 'Parent':
    //      Male → Son, Female → Daughter, Neutral → Child
    //  (Kept as constants so a future admin can change the lookup
    //   config and we can switch to a dynamic query if needed.)
    // ──────────────────────────────────────────────────────────────────
    private static final String TYPE_PARENT    = 'Parent';
    private static final String TYPE_SON       = 'Son';
    private static final String TYPE_DAUGHTER  = 'Daughter';
    private static final String TYPE_CHILD     = 'Child';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * For every child→parent pair in <em>parentIdByChildId</em>, creates two
     * Relationship records (one in each direction) unless a Relationship
     * between those two Contacts already exists (any Type, any direction).
     *
     * @param parentIdByChildId  child Contact Id → parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // ── Guard: nothing to do ──────────────────────────────────────
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── 1. Collect every unique Contact Id we will touch ──────────
        Set<Id> childIds   = new Set<Id>(parentIdByChildId.keySet());
        Set<Id> parentIds  = new Set<Id>(parentIdByChildId.values());
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(childIds);
        allContactIds.addAll(parentIds);
        allContactIds.remove(null);

        if (allContactIds.isEmpty()) {
            return;
        }

        // ── 2. SOQL #1 – Contact Gender (needed for reciprocal Type) ─
        Map<Id, Contact> contactById = new Map<Id, Contact>(
            [SELECT Id, Gender FROM Contact WHERE Id IN :allContactIds]
        );

        // ── 3. SOQL #2 – existing Relationships among our contacts ───
        //    A pair is "taken" if ANY Relationship exists between the
        //    two Contacts, regardless of Type or direction.
        Set<String> existingPairKeys = new Set<String>();

        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM   npe4__Relationship__c
                WHERE  npe4__Contact__c       IN :allContactIds
                  AND  npe4__RelatedContact__c IN :allContactIds
              ]) {

            Id c1 = rel.npe4__Contact__c;
            Id c2 = rel.npe4__RelatedContact__c;

            // Canonical key: smaller Id first – handles both directions.
            String pairKey = (c1 < c2) ? (c1 + ':' + c2)
                                        : (c2 + ':' + c1);
            existingPairKeys.add(pairKey);
        }

        // ── 4. Build the new Relationship records ─────────────────────
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {

            Id parentId = parentIdByChildId.get(childId);

            // Skip null parent or degenerate self-reference
            if (parentId == null || childId == parentId) {
                continue;
            }

            // Build canonical pair key for the child↔parent pair
            String pairKey = (childId < parentId)
                                ? (childId + ':' + parentId)
                                : (parentId + ':' + childId);

            // Skip if ANY relationship already exists between these two
            if (existingPairKeys.contains(pairKey)) {
                continue;
            }

            // ── Determine the reciprocal Type from the child's Gender ──
            Contact child = contactById.get(childId);
            String childGender = (child != null) ? child.Gender : null;

            String parentToChildType;
            if      (childGender == 'Male')   { parentToChildType = TYPE_SON; }
            else if (childGender == 'Female') { parentToChildType = TYPE_DAUGHTER; }
            else                              { parentToChildType = TYPE_CHILD; }

            // ── Child → Parent  (Child sees "Parent") ─────────────────
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = TYPE_PARENT,
                npe4__Status__c         = STATUS_CURRENT
            ));

            // ── Parent → Child  (Parent sees "Son" / "Daughter" / "Child") ──
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c           = parentToChildType,
                npe4__Status__c         = STATUS_CURRENT
            ));
        }

        // ── 5. DML – single bulk insert ──────────────────────────────
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
```

**Design notes**

| Concern | How it is handled |
|---|---|
| **Null / empty input** | Early `return` before any query or DML. |
| **Idempotent re-runs** | SOQL #2 retrieves every Relationship that involves any of the input Contacts (both `npe4__Contact__c` and `npe4__RelatedContact__c` sides). A canonical "pair key" (`min:sort`) is built in Apex; if the key already exists the pair is skipped entirely. |
| **Reciprocal Type (Son / Daughter / Child)** | Child's `Gender` is fetched in SOQL #1 and mapped to the correct reciprocal Type (matching the org's `npe4__Relationship_Lookup__c` "Parent" entry: Male → Son, Female → Daughter, Neutral → Child). |
| **Exactly one record per direction** | Two records are created per non-skipped pair: Child→Parent (Type *Parent*) and Parent→Child (Type *Son / Daughter / Child*). |
| **Bulk-safe** | Two SOQL queries and one `insert` regardless of whether the map has 1 pair or 200. No queries or DML inside loops. |

