public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {

        // If the running user has no access to the object at all, return empty.
        Schema.DescribeSObjectResult objDesc = FB_Employee__c.SObjectType.getDescribe();
        if (!objDesc.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build the SELECT list with only fields the running user can read.
        List<String> fields = new List<String>{ 'Id', 'Name' };

        if (FB_Employee__c.Department__c.getDescribe().isAccessible()) {
            fields.add('Department__c');
        }
        if (FB_Employee__c.Salary__c.getDescribe().isAccessible()) {
            fields.add('Salary__c');
        }
        if (FB_Employee__c.Personal_Email__c.getDescribe().isAccessible()) {
            fields.add('Personal_Email__c');
        }

        // Dynamic SOQL avoids selecting fields the user cannot read (which would
        // throw).  With-sharing context on the class enforces record-level sharing.
        String soql = 'SELECT ' + String.join(fields, ', ')
                    + ' FROM FB_Employee__c'
                    + ' ORDER BY Name ASC';

        return Database.query(soql);
    }
}
