```apex
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Build Account sObject shards – no SOQL needed, we only need Id + OwnerId.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // DML 1 – Account update with ALL Account trigger actions bypassed.
        // try/finally guarantees the bypass is cleared whether the DML succeeds or throws,
        // so Account automation is back to normal for the remainder of the transaction.
        try {
            TriggerBase.bypass(Schema.SObjectType.Account);
            update accountsToUpdate;          // all-or-none (default); exceptions propagate
        } finally {
            TriggerBase.clearBypass(Schema.SObjectType.Account);
        }

        // SOQL 1 – fetch child Contacts for the reassigned Accounts (bulk-safe, ≤200 parents).
        List<Contact> contacts = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

        if (!contacts.isEmpty()) {
            // Build Contact sObject shards – Contact triggers run normally (never bypassed).
            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact c : contacts) {
                contactsToUpdate.add(new Contact(Id = c.Id, OwnerId = newOwnerId));
            }

            // DML 2 – all-or-none; Contact trigger actions fire normally.
            update contactsToUpdate;
        }
    }
}
