/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease.
 * No inserts, updates, deletes, or SOQL — records are constructed in memory
 * and the action's beforeUpdate method is invoked directly.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    // ── Behaviour 1: reduction of MORE than half is rejected ──────────────
    @IsTest
    static void reductionMoreThanHalf_rejected() {
        Id fakeId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 499);

        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp };
        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(newOpp.hasErrors(),
            'Expected an error when Amount drops from 1000 to 499 (more than half)');
        System.assertEquals(1, newOpp.getErrors().size(),
            'Expected exactly one error');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp.getErrors()[0].getMessage(),
            'Error message should match ERROR_MESSAGE constant');
    }

    // ── Behaviour 2: reduction of EXACTLY half is accepted ────────────────
    @IsTest
    static void reductionExactlyHalf_accepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 500);

        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp };
        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(),
            'Expected NO error when Amount drops from 1000 to 500 (exactly half)');
    }

    // ── Behaviour 3: increase is accepted ─────────────────────────────────
    @IsTest
    static void increase_accepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 500);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 1000);

        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp };
        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(),
            'Expected NO error when Amount increases from 500 to 1000');
    }

    // ── Behaviour 4: null previous Amount handled without exception ───────
    @IsTest
    static void nullPreviousAmount_accepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        // Old record has no Amount set (null)
        Opportunity oldOpp = new Opportunity(Id = fakeId);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 100);

        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp };
        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp };

        // Should NOT throw a NullPointerException
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(),
            'Expected NO error when previous Amount is null');
    }

    // ── Behaviour 5: mixed batch – only violating records get the error ───
    @IsTest
    static void mixedBatch_onlyViolatingRecordsGetErrors() {
        Id id1 = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);
        Id id2 = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);
        Id id3 = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        // id1: 1000 → 400  (more than half drop → ERROR)
        // id2: 1000 → 600  (less than half drop → NO ERROR)
        // id3: 500  → 500  (no change         → NO ERROR)

        Opportunity old1 = new Opportunity(Id = id1, Amount = 1000);
        Opportunity old2 = new Opportunity(Id = id2, Amount = 1000);
        Opportunity old3 = new Opportunity(Id = id3, Amount = 500);

        Opportunity new1 = new Opportunity(Id = id1, Amount = 400);
        Opportunity new2 = new Opportunity(Id = id2, Amount = 600);
        Opportunity new3 = new Opportunity(Id = id3, Amount = 500);

        List<Opportunity> triggerNew = new List<Opportunity>{ new1, new2, new3 };
        List<Opportunity> triggerOld = new List<Opportunity>{ old1, old2, old3 };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        // Only the first record should carry an error
        System.assert(new1.hasErrors(),
            'Record 1 (1000→400) should have an error');
        System.assert(!new2.hasErrors(),
            'Record 2 (1000→600) should NOT have an error');
        System.assert(!new3.hasErrors(),
            'Record 3 (500→500) should NOT have an error');

        // Verify the error message on the failing record
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            new1.getErrors()[0].getMessage(),
            'Record 1 error message should match ERROR_MESSAGE constant');
    }
