/**
 * Trigger Action that keeps Account.FB_Open_Case_Count__c in sync with the
 * number of open (IsClosed = false) Cases related to each Account.
 *
 * Registered via Trigger_Action__mdt for After Insert, After Update,
 * After Delete and After Undelete on Case.
 *
 * Budget per execution: 1 SOQL (aggregate) + 1 DML (Account update).
 */
public with sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    // ─── After Insert ────────────────────────────────────────────────────────
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            Case c = (Case) s;
            // Only an open case changes the open-case count on its account.
            if (c.AccountId != null && c.IsClosed == false) {
                accountIds.add(c.AccountId);
            }
        }
        recountAccounts(accountIds);
    }

    // ─── After Update ────────────────────────────────────────────────────────
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case cNew = (Case) triggerNew[i];
            Case cOld = (Case) triggerOld[i];

            // If neither AccountId nor IsClosed changed the open-case count
            // cannot have changed for any account, so skip.
            if (cNew.AccountId == cOld.AccountId && cNew.IsClosed == cOld.IsClosed) {
                continue;
            }

            if (cNew.AccountId != null) {
                accountIds.add(cNew.AccountId);
            }
            if (cOld.AccountId != null && cOld.AccountId != cNew.AccountId) {
                accountIds.add(cOld.AccountId);
            }
        }
        recountAccounts(accountIds);
    }

    // ─── After Delete ────────────────────────────────────────────────────────
    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerOld) {
            Case c = (Case) s;
            // A deleted case that was open reduces its account's open count.
            if (c.AccountId != null && c.IsClosed == false) {
                accountIds.add(c.AccountId);
            }
        }
        recountAccounts(accountIds);
    }

    // ─── After Undelete ──────────────────────────────────────────────────────
    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            Case c = (Case) s;
            // An undeleted open case increases its account's open count.
            if (c.AccountId != null && c.IsClosed == false) {
                accountIds.add(c.AccountId);
            }
        }
        recountAccounts(accountIds);
    }

    // ─── Shared recount logic (1 SOQL + 1 DML) ──────────────────────────────
    private void recountAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1 – count remaining open cases per affected account.
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE IsClosed = false
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            openCountByAccount.put(
                (Id) ar.get('AccountId'),
                (Integer) ar.get('cnt')
            );
        }

        // Build the update list – accounts not present in the aggregate
        // result have zero open cases and must be set to 0 (not null/blank).
        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Integer count = openCountByAccount.containsKey(accId)
                ? openCountByAccount.get(accId)
                : 0;
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = count
            ));
        }

        // DML 1 – single bulk update.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
