/**
 * Singleton that holds parent Account data for the current trigger execution.
 * The inner Service class (registered as a Trigger Action) populates accountsById
 * via a single SOQL query so that downstream actions share one query per execution.
 */
public with sharing class TA_Contact_Queries {

    public Map<Id, Account> accountsById;

    private static TA_Contact_Queries instance;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action (Order 1) that queries parent Accounts for all Contacts
     * in the current trigger context. Re-runs on every trigger execution so
     * that recursive DML involving other Accounts still receives fresh data.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            List<Contact> contacts = (List<Contact>) triggerNew;

            Set<Id> accountIds = new Set<Id>();
            for (Contact c : contacts) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            TA_Contact_Queries instance = TA_Contact_Queries.getInstance();

            if (accountIds.isEmpty()) {
                instance.accountsById = new Map<Id, Account>();
            } else {
                instance.accountsById = new Map<Id, Account>(
                    [SELECT Id, BillingStreet, BillingCity, BillingPostalCode,
                            BillingCountry, AccountSource
                     FROM Account
                     WHERE Id IN :accountIds]
                );
            }
        }
    }
}
