/**
 * Trigger action (Order 20) that copies the parent Account's AccountSource into
 * a new Contact's LeadSource when LeadSource is blank and the Account has a
 * non-blank AccountSource. Contacts without an Account are left alone.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }

            if (String.isNotBlank(c.LeadSource)) {
                continue;
            }

            Account acct = queries.accountsById.get(c.AccountId);
            if (acct != null && String.isNotBlank(acct.AccountSource)) {
                c.LeadSource = acct.AccountSource;
            }
        }
    }
}
